			"config_auto_str_132": "</textarea>\t\t\t\t\t\t\t</div>\t\t\t\t\t\t\t<div class=\"ssl-con-key pull-left\">Certificato (formato PEM)<br>\t\t\t\t\ t\t\t\t<textarea id=\"csr\" class=\"bt-input-text\">",
