			"config_auto_str_156": "Eliminazione del certificato e riavvio del pannello in corso...",
			"config_auto_str_157": "Gestione delle autorizzazioni temporanee",
			"config_auto_str_158": "<div class='pd20'>\t\t\t\t\t<button class='btn btn-success btn-sm refresh_log'>AggiornaLog</button>\t\t\t\t\t<div class='divtable mt10'>\t\t\t\t\t\t<table class='table table-hover'>\t\t\t\t\t\t\t<thead>\t\t\t\t\t\t\t\t<tr><th>AzioneTipo</th><th>AzioneOra</th><th>Log</th></tr>\t\t\t\t\t\t\t</thead>\t\t\t\t\t\t\t<tbody id='logs_list'></tbody>\t\t\t\t\t\t</table>\t\t\t\t\t</div>\t\t\t\t</div>",
