			"config_auto_str_166": "Imposta la risposta \"Stato\" in caso di mancata autenticazione",
			"config_auto_str_167": "Invia",
			"config_auto_str_168": "Chiudi",
			"config_auto_str_169": "<div class=\"bt-form bt-form pd20\" > <div class=\"line\"> <span class=\"tname\">Stato corrispondente</span> <div class=\"info-r\"> <select class=\"bt-input-text mr5\" name=\"status_code\" style=\"width: 250px; \"></select> </div> </div> <ul class=\"help-info-text c7\"><li style=\"color: red;\">Risposta visualizzata quando non si è effettuato l’accesso e non è stato inserito correttamente il codice di sicurezza, utilizzata per nascondere le caratteristiche del pannello</li></ul> </div>",
			"config_auto_str_170": "Impostazioni predefinite - Errore di accesso a Sicurezza - Suggerimento",
			"config_auto_str_171": "403-Accesso negato",
			"config_auto_str_172": "La pagina 404 non esiste",
			"config_auto_str_173": "416-Richiesta non valida",
			"config_auto_str_174": "408-Timeout del client",
